window.NEWS=[{"title": "政院不副署老福法修法民進黨團：支持卓榮泰決定", "url": "https://www.cna.com.tw/news/aipl/202611060317.aspx", "date": "2026-11-06", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "行政院11月6日宣布不副署立法院10月16日三讀的老人福利法第22條修正案，指修法刪除部分醫療補助法源、增加鉅額財政負擔並違反權力分立。民進黨團表示支持，因修正案未公布生效，現行第22條繼續適用，符合資格的長輩仍可依原規定申請健保部分負擔及健保未給付醫療費用補助；依行政院說明，約6.6萬名經濟弱勢長輩落在修法影響範圍，修法每年約增加400億元支出。"}, {"title": "嘉義縣樂齡假牙裝置破2萬人 整體滿意度99%", "url": "https://www.cna.com.tw/news/aloc/202611060174.aspx", "date": "2026-11-06", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "嘉義縣政府樂齡假牙計畫實施滿8年，已補助超過2萬名長者裝置假牙，整體滿意度達99%。補助對象為65歲以上長者及55歲以上原住民，相關資訊可向合約院所、各鄉鎮市衛生所或撥專線0800-780-999查詢。"}, {"title": "台南SBIR輔導展成果 南市府攜手在地企業打造智慧綠能公車亭", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8845597", "date": "2026-11-06", "category": "補助成果發表", "topic": "節能減碳", "unit": "臺南市政府", "summary": "台南市政府於11月6日舉辦捐贈記者會，市長黃偉哲感謝和欣光通、隆盛金盛、創玖科技等企業捐贈智慧綠能公車亭。公車亭結合太陽能發電、10kWh以上儲能電池與AI智慧照明，每座每年可節省約2,500度電、減少1,300公斤二氧化碳，並具備遮陽、避雨、照明及未來可擴充的安全監控與充電功能。"}, {"title": "老人與身心障礙者於農業法人及團體消費補助作業要點", "url": "https://agriculture.tycg.gov.tw/News_Content.aspx?n=10616&s=1956861", "date": "2026-11-06", "category": "補助資訊", "topic": "社福與生活", "unit": "桃園市政府", "summary": "桃園市政府農業局訂定作業要點，補助設籍並實際居住桃園市、持有敬老愛心卡的老人及身心障礙者，於本市農（漁）會等農業法人及團體消費。每月可用核發點數中200點為上限扣抵採買產品，菸酒類及農業生產資材除外，新臺幣一元扣抵一點。農業法人及團體每月15日前送交前月交易紀錄請款；行動不便者可由親友持證件及卡片代購。"}, {"title": "立院三讀老農津貼調高為每月1.5萬元 回溯至7/1生效", "url": "https://www.cna.com.tw/news/aipl/202611060186.aspx", "date": "2026-11-06", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "立法院11月6日三讀修正老年農民福利津貼暫行條例，將老農津貼由每月8110元提高至1萬5000元，第4條溯及115年7月1日生效；並增訂發放額度滿2年檢討，若CPI成長率達3%即調整，增加經費由中央全額負擔。排富門檻同步放寬，個人綜合所得總額由50萬元調整至60萬元，土地及房屋財產價值由500萬元調整至1025萬元，行政院預計新增逾7000人可領取。"}, {"title": "116年度「文化部扶植青年藝術發展補助」11/5-12/4受理申請", "url": "https://culture.tycg.gov.tw/News_Content.aspx?n=11104&s=1957179", "date": "2026-11-06", "category": "補助資訊", "topic": "文化", "unit": "桃園市政府", "summary": "文化部推辦116年度「扶植青年藝術發展補助」計畫，申請對象為18歲至40歲（民國76年至98年出生）之青年藝術創作者。補助項目涵蓋視覺、表演或跨領域藝術之國內青年藝術發展相關計畫。受理申請期間為115年11月5日至12月4日，有意願申請者須透過文化部補助資訊網提交資料。"}, {"title": "「區公所補助款業務」廉政防貪指引-承辦人員未即時清查戶籍異動，已故長者敬老禮金遭冒領", "url": "https://www.wrs.taichung.gov.tw/3408154/post", "date": "2026-11-06", "category": "補助政策", "topic": "社福與生活", "unit": "臺中市政府", "summary": "臺中市政府水利局政風室於2026年11月6日發布廉政防貪指引，說明區公所補助款業務承辦人員未即時清查戶籍異動，導致已故長者的敬老禮金被冒領，提醒相關單位加強查核以防止補助金流失。"}, {"title": "立院調高老農津貼至1.5萬政院：超出預算支應能力", "url": "https://www.cna.com.tw/news/aipl/202611060307.aspx", "date": "2026-11-06", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "立院通過老農津貼修正案，擬將金額調至每月1.5萬元。政院回應此舉超出預算支應能力，並可能影響其他農業資源。農業部長陳駿季表示，若調高至1.5萬元需額外追加約300億至320億元預算，目前追加預算已不足以支應，且面臨無經費追溯發放的問題。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202611070075.aspx"}]}, {"title": "老農津貼每月1.5萬元綠：在野修法不負責任", "url": "https://www.cna.com.tw/news/aipl/202611060225.aspx", "date": "2026-11-06", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "立法院於11月6日三讀通過老年農民福利津貼暫行條例修正案，將老農津貼由現行的每月8,110元提高至每月1萬5000元。修法包含新增物價上漲檢討機制，發放額度2年後若CPI成長率達3%將進行調整，經費由中央全額負擔。民進黨對此表示質疑，認為在野修法將增加財政負擔，排擠其他農業政策與建設空間，且無法追溯補發今年7月至12月的津貼差額。"}, {"title": "製藥公協會齊呼籲暫緩擴大長者健保補助應先評估財源", "url": "https://www.cna.com.tw/news/afe/202611050289.aspx", "date": "2026-11-05", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "立法院日前修法擴大由中央全額補助符合條件的65歲以上長者健保費。製藥公會、製藥發展協會及學名藥協會11月5日發表聯合聲明，呼籲暫緩全面擴大長者保費補助，應優先完成財源、補助範圍及長期財務影響評估，並說明經費來源與超支因應方式，同時聽取病友與社福團體意見，兼顧長者保費負擔與醫藥照護體系持續運作。"}, {"title": "為配合文化部推動上元節民俗保存與傳承，請有關宗教團體辦理相關活動並踴躍申請補助", "url": "https://www.chcg.gov.tw/TSO/puxin/04bulletin/bulletin02_con.aspx?bull_id=440840", "date": "2026-11-05", "category": "補助資訊", "topic": "文化", "unit": "彰化縣政府", "summary": "彰化縣埔心鄉公所轉知，內政部已於115年9月4日發布「內政部促進宗教國際交流及文化發展補助作業要點」，補助對象包含依法登記或立案滿一年之寺廟、宗教財團法人及社團法人等。為配合文化部推動上元節民俗保存與傳承，請符合資格的宗教團體辦理上元節民俗調查研究、保存紀錄、傳習教育、人才培育、數位典藏及國際交流等活動，並依要點申請補助。"}, {"title": "民生電價遠低於成本台電扛逾750億補貼盼立院支持預算撥補", "url": "https://www.cna.com.tw/news/afe/202611050336.aspx", "date": "2026-11-05", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "台電因民生電價遠低於成本，吸收超過新台幣750億元補貼，其中約720億元針對1300萬戶、每月用電700度以下的住宅與小商家。台電請求立法院支持預算撥補，以分擔全民用電成本並維持財務體質。"}, {"title": "A+通過現觀、藥華醫藥、鈺祥等3項計畫， 聚焦自主智慧電信、創新抗癌新藥及半導體關鍵濾材技術", "url": "https://service.moea.gov.tw/EE514/tw/aiip/50-8284.html", "date": "2026-11-05", "category": "補助政策", "topic": "創新研發", "unit": "經濟部", "summary": "經濟部產業技術司於5日審核通過現觀科技、藥華醫藥與鈺祥企業等三項前瞻研發計畫，分別聚焦意圖驅動自主智慧電信、創新抗癌雙特異性抗體以及半導體關鍵濾材技術，提升我國關鍵技術自主能力與產業競爭力。"}, {"title": "網傳越南生來台即享補助教部：獎學金有審查程序", "url": "https://www.cna.com.tw/news/ahel/202611050047.aspx", "date": "2026-11-05", "category": "補助政策", "topic": "就業與人才", "unit": "中央社", "summary": "教育部於11月5日澄清，台灣獎學金僅針對世界各國優秀學生，依中華民國駐外館處遴選並有名額限制，並非專為越南學生提供。獎學金每學期最高補助學雜費新台幣4萬元，生活費每月最高1.5萬元，需經學業、語言等審查，且不得重複領取其他政府或校方補助。"}, {"title": "政院通過平日國旅補助延至今年底加碼規劃Taiwan Pass五折方案", "url": "https://www.cna.com.tw/news/aipl/202611050128.aspx", "date": "2026-11-05", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "行政院通過平日國旅補助方案，延長至今年12月31日，並加碼規劃Taiwan Pass五折方案之第二波。此政策旨在鼓勵民眾於年底期間旅遊，透過平日住宿獎助與遊樂園留宿優惠，帶動觀光產業。交通部將負責相關執行計畫，並持續推動平日國旅優惠以因應國人旅遊需求。"}, {"title": "點明《老人福利法》修法三大問題 卓揆請衛福部通盤研商 回歸量能負擔、弱勢補助及永續財政原則", "url": "https://www.ey.gov.tw/Page/9277F759E41CCD91/92740cf4-2585-4cc7-8593-d6d9ffd90f9b", "date": "2026-11-05", "category": "補助政策", "topic": "社福與生活", "unit": "行政院", "summary": "行政院長卓榮泰於11月5日說明《老人福利法》修法，指出目前政府每年編列12.2億元補貼70歲以上低收入戶與中低收入戶的健保費，修法後將把65歲以上長者的健保補助範圍擴大至八成以上，預估一年增加約400億元經費，未來二、三十年補助費用可能超過600億元，並要求衛福部在綜整意見後審慎研商，確保弱勢補助與永續財政。"}, {"title": "桃園節能減碳有成! 17家企業年省1,446萬度電 住宅節能補助照顧老幼", "url": "https://www.tycg.gov.tw/NewsPage_Content.aspx?n=7&s=1954284", "date": "2026-11-05", "category": "補助政策", "topic": "節能減碳", "unit": "桃園市政府", "summary": "桃園市政府推動「高溫敏感族群降溫節能補助計畫」，針對0至6歲幼童與65歲以上長者提供空調清洗、一級能效冷氣與玻璃隔熱膜補助，申請至10月底止；另於8月5日表揚17家住商用電績優單位，合計節省1,446萬度電，顯示住宅與商業共同減碳成效。"}, {"title": "最新消息-原住民族委員會116年度原住民身心障礙者機構式服務生活資材費用補助", "url": "https://www.ipc.gov.taipei/News_Content.aspx?n=EA2FD0F6539FEB5C&sms=78D644F2755ACCAA&s=9CDE0D921CDDC1A5", "date": "2026-11-04", "category": "補助資訊", "topic": "原住民", "unit": "臺北市政府", "summary": "原住民族委員會（中央原民會）辦理116年度原住民身心障礙者機構式服務生活資材費用補助計畫，實施期程自116年1月1日至12月31日，或於經費用罄時即告中止受理。申請期限為116年1月1日至4月30日，對象為財（社）團法人住宿式機構及主管機關認可之社會福利機構，依個案每人每月補助3,000至7,200元，項目含個人衛生耗材、醫療耗材及營養品。"}, {"title": "清大研發智慧水質治理技術整合污染分解與監測", "url": "https://www.cna.com.tw/news/aloc/202611040113.aspx", "date": "2026-11-04", "category": "補助成果發表", "topic": "創新研發", "unit": "中央社", "summary": "海委會補助國立清華大學與國立台灣大學研發智慧水質治理技術。計畫針對鉛、汞、鎘等重金屬離子研發專用感測膜，並整合機械能促進有機污染物分解技術。經測試驗證，特定條件下處理40分鐘後有機污染物去除率超過90%，未來將延伸應用於近岸水質預警、智慧養殖及海洋生態保護等場域。"}, {"title": "台荷攜手4項跨國研發合作布局先進光子封裝、AI資料中心", "url": "https://www.cna.com.tw/news/afe/202611040086.aspx", "date": "2026-11-04", "category": "補助成果發表", "topic": "創新研發", "unit": "中央社", "summary": "經濟部產發署宣布，台荷透過「科技搭橋計畫」促成4項跨國研發合作，涵蓋先進光子封裝、5G/6G高速通訊、AI資料中心及量子運算。產發署副署長陳國軒於11月2日率團赴荷與荷蘭經濟暨氣候部交流，並於11月3日率領企業與法人機構見證工研院、台灣光電暨化合物半導體產業協會（TOSIA）及荷蘭PhotonDelta簽署三方合作備忘錄。"}, {"title": "臺南產業數位轉型邁向新階段 市府串聯產業共創數位競爭力", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8845245", "date": "2026-11-04", "category": "補助成果發表", "topic": "數位轉型與AI", "unit": "臺南市政府", "summary": "臺南市政府經濟發展局於115年11月4日舉辦產業數位轉型應用計畫成果發表會，說明自112年推動以來已諮詢輔導235家中小企業、招募118家供應服務廠商，並提供共計505萬元技術導入補助。會中有合成帆布行、幸福良食有限公司及上進有限公司等三家企業分享數位轉型案例，展示政府如何協助企業提升營運效率與永續發展。"}, {"title": "農業部116年度歲出預算估1986.7億年增150億元", "url": "https://www.cna.com.tw/news/ahel/202611040093.aspx", "date": "2026-11-04", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "農業部編列116年度歲出預算約新台幣1986.73億元，較115年度增加約150億元，增列項目包括老年農民福利津貼38.61億元、撥補農業天然災害救助基金37.57億元、縣市管谷川及排水整體改善計畫12.2億元，另新增撥補農村再生基金29.19億元。"}, {"title": "一百一十五年度第三季補助情形公告", "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=givensubsidy&id=326&serno=e23cc6a5-99f2-412d-869c-4101f102299f", "date": "2026-11-04", "category": "補助資訊", "topic": "綜合", "unit": "客家委員會", "summary": "客家委員會於115年11月4日在獎補助結果專區發布「一百一十五年度第三季補助情形公告」，並附有115年第3季公告獎補助資料可供下載查閱。"}, {"title": "賴清德盼通過追加預算撥補中油台電助平抑物價", "url": "https://www.cna.com.tw/news/aipl/202611040249.aspx", "date": "2026-11-04", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "民進黨中常會上，總統賴清德說明115年度總預算追加案中，撥補中油1014億元、增資2338億元，台電補貼711億元，旨在平抑物價，並請立法院黨團協助與國民黨溝通。同時，116年中央總預算案列600億元撥補健保基金，以避免健保費上漲。"}, {"title": "函轉辦理廚餘養豬場之轉型飼料補助措施", "url": "https://www.xinwu.tycg.gov.tw/News_Content.aspx?n=5603&s=1951581", "date": "2026-11-04", "category": "補助資訊", "topic": "農業", "unit": "桃園市政府", "summary": "桃園市新屋區公所農經課於115年11月4日公告「函轉辦理廚餘養豬場之轉型飼料補助措施」，並附相關公文與附件檔案，公告期間至115年12月31日。", "also": [{"unit": "桃園市政府", "url": "https://www.longtan.tycg.gov.tw/News_Content.aspx?n=5597&s=1954276"}]}, {"title": "追加預算案中油擬增資2338億龔明鑫：10年增25部天然氣機組", "url": "https://www.cna.com.tw/news/aipl/202611040104.aspx", "date": "2026-11-04", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "經濟部長龔明鑫說明，115年度中央政府追加預算案共編列6076億元，其中中油補貼1014億元、增資2338億元，台電補貼711億元。未來10年將增設25部天然氣大型機組，並建置7座接收站及3條管線，以穩定油價、電價及CPI。"}, {"title": "蘇花安動土預定民國121年完工 台北到花蓮只約2小時", "url": "https://www.cna.com.tw/news/ahel/202611040284.aspx", "date": "2026-11-04", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "行政院長卓榮泰於11月4日在宜蘭東澳主持「蘇花安」動土祈福典禮，計畫投入新台幣1056億元，於民國121年完工通車。完工後台北至花蓮行車時間將縮短至約2小時，提升東部道路安全與抗災能力。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202611040319.aspx"}]}, {"title": "屏東內埔、新園衛生所接連揭牌持續推動10所重建", "url": "https://www.cna.com.tw/news/aloc/202611040198.aspx", "date": "2026-11-04", "category": "補助成果發表", "topic": "社福與生活", "unit": "中央社", "summary": "屏東縣政府向中央爭取補助推動衛生所重建，11月4日內埔鄉與新園鄉衛生所已分別揭牌啟用。內埔鄉衛生所投入1億8000餘萬元，興建兩棟現代化建築；新園鄉衛生所則投入1億4000餘萬元。縣府未來計畫持續推動10所衛生所重建，其中5所經費已獲衛福部支持，並包含2處衛生室重建與耐震補強，以完善在地健康防護網。"}, {"title": "公告本公所115年度桃園市復興區補助小學推展美語計畫", "url": "https://www.fuxing.tycg.gov.tw/News_Content.aspx?n=5708&s=1951031", "date": "2026-11-04", "category": "補助資訊", "topic": "綜合", "unit": "桃園市政府", "summary": "桃園市復興區公所行政室於115年11月4日公告「115年度桃園市復興區補助小學推展美語計畫」，並附計畫與附件檔案，公告期間至115年11月20日。"}, {"title": "輝達落腳爭議民進黨團：不是單獨誰的功勞", "url": "https://www.cna.com.tw/news/aipl/202611030094.aspx", "date": "2026-11-03", "category": "補助政策", "topic": "數位轉型與AI", "unit": "中央社", "summary": "民進黨立法院黨團說明，輝達在台北設立AI研發中心，輝達出資新台幣176億元，經濟部補助新台幣67億元，相關補助案於2021年核准，2022年經濟部長王美花與黃仁勳會面討論布局，並於10月28日蔣萬安接受訪問。"}, {"title": "綠島文化健康站揭牌饒慶鈴：台東完成16鄉鎮市布建", "url": "https://www.cna.com.tw/news/aloc/202611030216.aspx", "date": "2026-11-03", "category": "補助成果發表", "topic": "社福與生活", "unit": "中央社", "summary": "台東縣府編列預算輔導設置綠島文化健康站，縣長饒慶鈴11月3日出席揭牌，台東16鄉鎮市增至116站，服務4200餘名長者，數量居全國第一。該站自115年9月30日起提供原住民族長者關懷照護、健康促進、文康休閒及營養餐飲服務。"}, {"title": "內政部表揚績優合作社期許成為守護基層韌性力量", "url": "https://www.cna.com.tw/news/aipl/202611030299.aspx", "date": "2026-11-03", "category": "補助成果發表", "topic": "綜合", "unit": "中央社", "summary": "內政部於11月3日舉辦第104屆國際合作社節表揚大會，表揚表現卓越的合作社及實務人員。常務次長吳堂安指出，合作社是社區安全與防災的關鍵夥伴，內政部將大力支持輔導民間團體辦理防災士培訓，並朝向40萬名防災士為目標。此外，台灣自民國114年起推動為期四年的「合作事業振興發展計畫」，透過育成輔導團隊、獎勵機制與資源挹注，支持合作社穩健經營並持續推動合作事業發展。"}, {"title": "促轉基金公私協力系列活動──「好計畫不只靠想像：從提案撰寫到實務執行」實體工作坊開放報名！", "url": "https://tjb.ey.gov.tw/page/647E69AD75BDDB28/4fe01e3e-895f-475e-95c6-30eadc513147", "date": "2026-11-03", "category": "補助資訊", "topic": "創新研發", "unit": "行政院", "summary": "民主韌性專案辦公室舉辦實體工作坊「好計畫不只靠想像：從提案撰寫到實務執行」，於115年11月15日（星期日）13:00至17:30舉行，旨在協助有意申請政府補助的個人、民間團體與專案工作者提升計畫撰寫與執行能力。報名截止於115年11月12日（星期四），錄取者將於11月13日以電子郵件通知活動地點。"}, {"title": "中油增資效益龔明鑫：降負債比有利借貸", "url": "https://www.cna.com.tw/news/aipl/202611030142.aspx", "date": "2026-11-03", "category": "補助資訊", "topic": "綜合", "unit": "中央社", "summary": "行政院長卓榮泰於立法院報告115年度中央政府追加預算案，包含補貼中油汽柴油與天然氣價格凍漲、緩漲經費新台幣1014億元，並增資中油2338億元。卓榮泰表示補貼是為了填補過去吸收的成本，盼藉穩定營運穩定民生。經濟部長龔明鑫指出，中油天然氣接收站與管線鋪設等新建設需經費4800多億元，先編列2338億元支付建設；增資後整體負債比可由目前的90%多下降，提升財務評等，有利於未來借貸利率。"}, {"title": "選手、教練化身漫畫顧問文化部攜運動部推3部台漫", "url": "https://www.cna.com.tw/news/acul/202611020192.aspx", "date": "2026-11-02", "category": "補助政策", "topic": "文化", "unit": "中央社", "summary": "文化部與運動部各出資新台幣500萬元，聯手徵選並資助三部以柔道、羽球、體操為題的台灣運動漫畫，葉宏蔚、詹又蓁等選手擔任顧問，計畫於明年首屆台灣國際漫畫節展出。"}, {"title": "三、生產、生活及生態三合一：有機水稻產業的永續發展-有機稻米館", "url": "https://kmweb.moa.gov.tw/subject/subject.php?id=66288", "date": "2026-11-02", "category": "補助政策", "topic": "農業", "unit": "農業部", "summary": "農業部依《有機農業促進法》推動有機水稻永續發展，兼顧生產、生活與生態三合一。截至115年2月底，全國有機及友善環境耕作面積合計28,765公頃，占國內耕地面積3.7%。臺中區農業改良場於113年整理中部有機及友善水稻栽培技術供民參考。農業部農糧署亦輔導有機農產品市集與企業永續採購，建立區域型有機稻米產銷體系。"}, {"title": "本分署辦理116學年度「補助大專校院就業學程企業預聘青年計畫」申請說明暨媒合會，歡迎大專校院及企業踴躍報名參與!!", "url": "https://thmr.wda.gov.tw/News_Content.aspx?n=DE4C0FE1DE37E6E0&sms=6A5E82A16F18A41D&s=A8E801B6D8240DB6", "date": "2026-11-02", "category": "補助資訊", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動部勞動力發展署桃竹苗分署為讓轄區大專校院及企業瞭解「補助大專校院就業學程企業預聘青年計畫」內容及申請方式，將辦理2場計畫說明會並安排產學交流媒合。竹苗場於115年11月10日（星期二）在新竹市政府勞工及青年處身障就業綜合大樓舉行，須於11月4日（三）下午3時前線上報名；桃園場於115年11月12日（星期四）在健行科技大學舉行，須於11月6日（五）下午3時前線上報名。媒合採預約制。"}, {"title": "花蓮漁港儲冰廠及冷凍庫新建計畫縣府攜手漁會推進", "url": "https://www.cna.com.tw/news/aloc/202611020167.aspx", "date": "2026-11-02", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "2024年0403地震造成花蓮既有製冰廠受損且不再修復，花蓮縣府持續協助漁會協調替代供冰管道。縣府農業處表示，「花蓮漁港儲冰廠及冷凍庫新建計畫」總經費約新台幣1億2194萬元，中央研議以7成經費補助地方推動冷鏈設施改善。目前花蓮籍漁船共429艘，每月約200多艘出海作業。"}, {"title": "健保數位轉型智慧醫療扎根中台灣！ 攜手產官學引領基層院所迎向數位新紀元- 公共關係室", "url": "https://dep.mohw.gov.tw/pro/cp-2731-88338-120.html", "date": "2026-11-01", "category": "補助成果發表", "topic": "數位轉型與AI", "unit": "衛生福利部", "summary": "衛生福利部中央健康保險署推動「基層醫療院所資訊服務系統雲端轉型補助計畫」，自114年起推動為期三年，總計挹注3億元經費協助基層院所克服硬體維護與資安防護痛點。計畫推行首年度全臺已有771家西、中、牙醫診所及社區藥局完成導入，串聯電子處方箋、電子病歷及線上預約。健保署於11月1日在逢甲大學舉辦觀摩會，交流轉型經驗並助力中臺灣基層醫療升級。"}, {"title": "賴總統：穩定社會不漲油電健保盼在野黨支持預算", "url": "https://www.cna.com.tw/news/aipl/202611010068.aspx", "date": "2026-11-01", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "賴清德總統於1日出席高雄市醫師公會新會館啟用典禮，說明今年稅收增加，政府已追加預算補助給中油與台電，並以稅收挹注健保，避免調漲健保費，期盼在野黨支持此預算。"}, {"title": "獎勵青年地方創生龔明鑫：若拓展海外經濟部可協助", "url": "https://www.cna.com.tw/news/afe/202611010162.aspx", "date": "2026-11-01", "category": "補助成果發表", "topic": "中小企業與新創", "unit": "中央社", "summary": "經濟部長龔明鑫於2026年11月1日出席115年度獎勵青年投入地方創生行動計畫成果發表會，說明政府提供一般組每隊35萬元、利他組每隊68萬元獎勵金，並搭配專業輔導與培力課程。自112年起已累計支持303隊青年團隊，未來若有商業化或拓展海外需求，經濟部中小及新創企業署可協助。"}, {"title": "平日住宿獎助登記可申請點數500點雙人玩樂園", "url": "https://www.cna.com.tw/news/ahel/202610310037.aspx", "date": "2026-10-31", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "交通部觀光署於10月31日宣布，凡在國旅住宿補助系統登記平日住宿獎助並同意提供資料者，可於退房當日下午3時起至平台申請點數。首晚可獲800點，連住第二晚再加1200點，單人最高2000點。點數可兌換全台18家遊樂園門票或商品，例如500點即可雙人入園東勢林場遊樂區，800點可換九族文化村長者雙人套票。已使用平日住宿獎助的民眾，只要在9、10月登記並勾選同意，即可依實際住宿晚數申請點數。"}, {"title": "總統：助企業組聯合艦隊布局海外穩固國內產業發展", "url": "https://www.cna.com.tw/news/aipl/202610300161.aspx", "date": "2026-10-30", "category": "補助政策", "topic": "數位轉型與AI", "unit": "中央社", "summary": "總統賴清德於10月30日表示，政府將持續串聯部會與專業資源，協助大型企業帶領供應鏈上下游廠商組成聯合艦隊，於海外布局聚落，並透過8年新台幣1000億元的計畫穩固國內產業發展，同時加速中小微企業的數位、智慧與淨零轉型。政府亦指出，明年度科技預算已突破新台幣2000億元，創下歷年新高。"}, {"title": "116年度「從智慧健康到永續深化：健康永續醫院的整合實踐計畫」補(捐)助科技發展計畫徵求說明書及契約書", "url": "https://mohw.gov.tw/cp-18-88330-1.html", "date": "2026-10-30", "category": "補助政策", "topic": "綜合", "unit": "衛生福利部", "summary": "衛生福利部公告116年度健康永續醫院整合實踐計畫補助徵求說明書與契約書，申請單位須於公告日起至115年11月5日下午5時止送件，逾時不受理。"}, {"title": "【澄清稿】澄清「婦女再就業計畫」未委託或補助第三方辦理說明會、開設自主訓練課程、代辦申請等相關事宜", "url": "https://www.mol.gov.tw/1607/1632/2660/99889/post", "date": "2026-10-30", "category": "補助政策", "topic": "就業與人才", "unit": "勞動部", "summary": "勞動部澄清，為協助退出勞動市場180日以上的婦女重返職場，提供「婦女再就業計畫－自主訓練獎勵」：婦女可自行找課程，訓練前向勞動力發展署所屬分署提出訓練計畫，經核定並完成訓練、辦理求職登記後可申請獎勵金2萬元，訓練後180日內就業可再申請1萬元，合計最高3萬元。勞動部及所屬勞動力發展署、各分署均未委託或補助任何第三方辦理說明會、開課或代辦申請，提醒民眾勿因不明訊息提供個資、繳費或報名課程。"}, {"title": "桃園影視政策深耕有成！補助、協拍、電影節三軌齊發國內外大獎橫掃不斷打造國際級影視友善之都", "url": "https://culture.tycg.gov.tw/News_Content.aspx?n=11103&s=1935528", "date": "2026-10-30", "category": "補助政策", "topic": "文化", "unit": "桃園市政府", "summary": "桃園市政府自112年起推動影視補助、協拍支援與桃園電影節三軌並進，協拍服務案量突破3,400件，補助作品屢獲金馬、金鐘等國內外大獎。2024年電影獎金提升至125萬元，2025年改稱「桃園電影獎」，2026年新增特效與動畫獎，總獎金升至135萬元。2026年電影節票房突破44萬元，參與人次達7,052人，並舉辦國際論壇吸引逾650人次。"}, {"title": "東勢客家文化園區整建開工江啟臣何欣純出席支持", "url": "https://www.cna.com.tw/news/aloc/202610300170.aspx", "date": "2026-10-30", "category": "補助成果發表", "topic": "客家", "unit": "中央社", "summary": "台中市建設局辦理「東勢客家文化園區整建工程」，10月30日舉行開工祈福典禮，由市府副秘書長林育鴻主持，立法院副院長江啟臣、立委何欣純出席。建設局長陳大田說明，工程經費新台幣7461萬元，其中中央補助5820萬元、市府自籌1641萬元。工程以修復東勢火車站歷史風貌為核心，結合站體整建、前庭景觀改善及停車空間優化，延續山城鐵道記憶與客家文化特色。"}, {"title": "青年海外圓夢計畫成果展賴總統：把世界解方帶回台灣", "url": "https://www.cna.com.tw/news/aipl/202610300097.aspx", "date": "2026-10-30", "category": "補助成果發表", "topic": "就業與人才", "unit": "中央社", "summary": "115年青年百億海外圓夢基金計畫成果展於10月30日在高雄展覽館舉行，為期三天。總統賴清德出席並表示，政府協助年輕人走向國際、學習空氣污染檢測、魔術技藝、無人機技術等，期望將世界的解方帶回台灣。教育部次長劉國偉說明，今年首次推出「圓夢助力方案」，弱勢青年錄取率由7%提升至14%。"}, {"title": "退輔會慶祝榮民節傳承「衛國無悔」榮民精神", "url": "https://www.cna.com.tw/news/aipl/202610300290.aspx", "date": "2026-10-30", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "退輔會主委嚴德發於10月30日舉行成立72週年暨第48屆榮民節慶祝大會，宣布自今年10月1日起，將補助範圍擴大至國軍各醫院，全面落實榮民健康照顧。此補助延續去年9月1日全額補助有職榮民至榮民醫療機構就醫的健保部分負擔，並將於明年1月1日啟動退除役官兵軍民專長轉銜平台，持續推動就學、就業、就醫、就養及服務照顧。"}, {"title": "勞動部：3行業11月起適用僱用安定薪資補貼", "url": "https://www.cna.com.tw/news/ahel/202610290174.aspx", "date": "2026-10-29", "category": "補助政策", "topic": "就業與人才", "unit": "中央社", "summary": "勞動部宣布，自11月1日起機械設備製造業、其他運輸工具及其零件製造業以及化學材料及肥料製造業可適用僱用安定薪資補貼。雇主若協議減班休息30日以上，且受僱勞工列冊通報，可領補貼，補助減班前後薪資差額70%，每月最高1萬1500元，適用期間至116年4月30日止。"}, {"title": "視察花蓮漁港儲冰廠及冷凍庫新建工程規劃進度 卓揆：中央提高工程補助至7成 兼顧食安與漁民權益", "url": "https://www.ey.gov.tw/Page/9277F759E41CCD91/5290e58c-af6c-4052-870d-884d8ddb68a1", "date": "2026-10-29", "category": "補助政策", "topic": "農業", "unit": "行政院", "summary": "行政院長卓榮泰於10月29日視察花蓮漁港儲冰廠及冷凍庫新建工程，指出總經費約1億2千萬元，政府補助比例由原先50%提升至70%，其餘30%由花蓮縣政府與花蓮區漁會共同負擔，並要求農業部加速補足全國漁港製冰設備。"}, {"title": "農業部發布「廚餘養豬場輔導轉型飼料補助要點」第4點、第8點、第9點（廚餘養豬場輔導轉型飼料補助第二階段申請案）", "url": "https://www.luzhu.tycg.gov.tw/News_Content.aspx?n=5714&s=1933468", "date": "2026-10-29", "category": "補助政策", "topic": "農業", "unit": "桃園市政府", "summary": "桃園市蘆竹區公所轉知，農業部發布「廚餘養豬場輔導轉型飼料補助要點」第4點、第8點及第9點規定，內容涉及廚餘養豬場輔導轉型飼料補助第二階段申請案，有意申請的養豬場可留意相關規定。", "also": [{"unit": "彰化縣政府", "url": "https://www.chcg.gov.tw/TSO/ershui/04bulletin/bulletin02_con.aspx?bull_id=440506"}]}, {"title": "高雄SBIR成果亮眼 智慧低碳創新接軌國際", "url": "https://www.kcg.gov.tw/News_Content.aspx?n=F29A02A9D36C47F0&sms=19902EF36D6B551D&s=A13AA1B330D879CC", "date": "2026-10-29", "category": "補助成果發表", "topic": "創新研發", "unit": "高雄市政府", "summary": "高雄市政府經濟發展局於115年10月28日舉辦「114年度高雄市SBIR計畫－雄好本領成果發表會」，邀請10家亮點廠商展示成果，並辦理產品發表與1對1商洽媒合。地方型SBIR已邁入第19年，114年共補助44家廠商，總補助金額逾3,215萬元，其中12家獲評為優秀廠商。市府將持續以研發補助、場域實證與國際鏈結，協助企業推動數位與淨零雙軸轉型。"}, {"title": "老農津貼若增至1.5萬元陳駿季：無經費追溯發放", "url": "https://www.cna.com.tw/news/ahel/202610290076.aspx", "date": "2026-10-29", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "農業部長陳駿季10月29日至立法院經濟委員會報告時表示，若老農津貼從現行標準增至新台幣1萬5000元，需追加約300至320億元預算。提高至1萬元今年追加64.5億元，若改為1萬5000元追加預算將來不及，年底前無法通過法令及預算時，今年將無經費追溯至7月發放差額。"}, {"title": "台灣女足拚世界盃稱後勤空窗足協規劃移訓、爭取津貼", "url": "https://www.cna.com.tw/news/aspt/202610290005.aspx", "date": "2026-10-29", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "中華足協為備戰11月28日於摩洛哥舉行的世界盃附加賽，規劃於11月8日集結並於10日或11日前往卡薩布蘭卡移地訓練，同時於10月15日後因津貼中斷，已於15日函請國訓中心協助銜接培訓津貼，相關預算已送交國訓中心，預計於11月4日召開審查會議。"}, {"title": "勞動部增設友善家庭職場科負責職代津貼、育兒減工時獎勵", "url": "https://www.cna.com.tw/news/ahel/202610280236.aspx", "date": "2026-10-28", "category": "補助政策", "topic": "就業與人才", "unit": "中央社", "summary": "為推動「台灣人口對策新戰略」中獎勵育兒減少工時、職代津貼等措施，勞動部經行政院人事行政總處同意，在勞動條件及就業平等司下增設「友善家庭職場科」，編制1名科長、4名科員，專責相關政策、預算編列執行及與地方政府推動事務。其中企業發職代津貼可獲補助，職代津貼補助為每日800元。"}, {"title": "轉知 農業部農村發展及水土保持署「116年農村社區綠色照顧計畫」案", "url": "https://www.chcg.gov.tw/TSO/dacheng/04bulletin/bulletin02_con.aspx?bull_id=440420", "date": "2026-10-28", "category": "補助申請", "topic": "農業", "unit": "彰化縣政府", "summary": "彰化縣大城鄉公所轉知，農業部農村發展及水土保持署推動「116年農村社區綠色照顧計畫」，因應農村人口高齡化與在地照顧需求，結合農業及社區資源，鼓勵青壯年投入，建立在地綠色照顧服務模式。計畫自115年10月19日上午9時起至11月20日下午5時開放申請，研提原則可至農村發展及水土保持署官網下載，並請農村再生社區踴躍參與。"}, {"title": "楊金龍：若無預算撥補與能源補貼油價續漲通膨率恐升", "url": "https://www.cna.com.tw/news/afe/202610280125.aspx", "date": "2026-10-28", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "中央銀行總裁楊金龍於10月28日在立法院財政委員會說明，若政府未持續提供預算撥補與能源補貼給中油、台電，且國際油價持續上漲，通膨率可能再度上升。央行預測2026年CPI年增率為2.03%，明年降至1.83%，認為物價情勢仍可接受，並指出能源價格穩定機制較升息更有效。"}, {"title": "產業新尖兵計畫補助最高10萬元訓練費，每月再發8千元學習獎勵金！", "url": "https://www.wda.gov.tw/News_Content.aspx?n=31&s=19491", "date": "2026-10-28", "category": "補助政策", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動部勞動力發展署推動「產業新尖兵計畫」，補助青年最高10萬元訓練費，並自116年起於訓練費內含最高8,000元AI工具訂閱補助；參訓者訓前自付1萬元，結訓90日內就業即可全額返還，且每月另領8,000元學習獎勵金，旨在提升青年就業競爭力。"}, {"title": "都更捐贈社宅效果遭質疑內政部：強烈要求公辦都更申請社宅容獎", "url": "https://www.cna.com.tw/news/aipl/202610280151.aspx", "date": "2026-10-28", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "行政院會7月通過修法，鼓勵業者在都市更新區無償捐贈社宅作為「婚育宅」，建築容積獎勵最高2倍；危老重建範圍內無償捐贈婚育宅或其他社福設施，基準容積將達1.45倍。立法院內政委員會10月28日舉辦修法公聽會，學者質疑容獎設計難以吸引捐贈；內政部次長董建宏表示，未來會強烈要求公辦都更一定要申請社宅容獎，作為第一要件。"}, {"title": "高市府推動市場全齡創業四年補助逾3,000萬元助攤商創新轉型2026高雄市場創業補助正式開放申請最高補助30萬", "url": "https://www.kcg.gov.tw/News_Content.aspx?n=F29A02A9D36C47F0&sms=19902EF36D6B551D&s=BE158A95361279BD", "date": "2026-10-28", "category": "補助政策", "topic": "中小企業與新創", "unit": "高雄市政府", "summary": "高雄市政府經濟發展局推動傳統市場活化，透過市場創業補助及專業輔導協助攤商改善營業環境、發展特色品牌，四年累計核定143件、補助經費逾3,000萬元。市府自114年起擴大補助對象，不再限青年，年滿18歲且符合資格的攤商均可申請，支持青年創業、二代接班及既有攤商轉型。經發局10月27日舉辦「115年度高雄市市場青年創業補助計畫」說明會，近百位攤商參與。"}, {"title": "鼓勵準公托人員長期留任 中市提供獎金最高3.6萬", "url": "https://www.cna.com.tw/news/aloc/202610270133.aspx", "date": "2026-10-27", "category": "補助政策", "topic": "就業與人才", "unit": "中央社", "summary": "台中市長盧秀燕於10月27日宣布，明年起試辦「準公共托嬰中心專任人員久任獎金」，依服務年資每人每年發給2萬4千元、3萬元或3萬6千元，鼓勵托育人員長期留任，提升照顧品質。"}, {"title": "雲林縣東勢鄉公所制定「雲林縣東勢鄉公所-東勢鄉立幼兒園幼童專用車交通費用及新生入園三好禮補助自治條例」", "url": "https://www.pingzhen.tycg.gov.tw/News_Content.aspx?n=5613&s=1927756", "date": "2026-10-27", "category": "補助政策", "topic": "社福與生活", "unit": "桃園市政府", "summary": "雲林縣東勢鄉公所制定「雲林縣東勢鄉公所-東勢鄉立幼兒園幼童專用車交通費用及新生入園三好禮補助自治條例」，就東勢鄉立幼兒園幼童專用車交通費用及新生入園三好禮訂定補助規定，發布單位為該所社會課。"}, {"title": "轉知內政部移民署辦理「新住民發展基金培力研習課程暨實務交流工作坊」提供免費業師諮詢輔導服務案之宣傳海報", "url": "https://www.chcg.gov.tw/DTO/labor/03bulletin/bulletin03_con.aspx?bull_id=440319", "date": "2026-10-27", "category": "補助政策", "topic": "社福與生活", "unit": "彰化縣政府", "summary": "勞工處就業服務科依據本府社會處115年10月19日函及內政部移民署115年10月15日函，轉知內政部移民署辦理「新住民發展基金培力研習課程暨實務交流工作坊」，提供有意願提案申請補助者免費的計畫書架構、內容檢視、效益設定、經費編列與核銷風險檢核等業師諮詢輔導服務，並公告相關海報資訊供使用。"}, {"title": "中市文化局推動歷史老屋再生 串聯城市文化脈絡 以州廳為核心重塑舊城文化新風貌", "url": "https://cleaner.epb.taichung.gov.tw/newsmain.aspx?n_id=26065", "date": "2026-10-26", "category": "補助政策", "topic": "文化", "unit": "臺中市政府", "summary": "台中市政府文化局自111年起推動「台中市歷史老屋再生補助作業要點」，提供建物整修、文化經營及歷史調查等全方位補助。近年多棟老屋在市府與民間合作下活化，包括「盛香堂」改建為「富興工廠1962」等案例。位於舊城區核心的國定古蹟台中州廳於2026年10月15日重新開放，成為文化園區，串聯舊城文化脈絡。"}, {"title": "構築智慧海域防線海委會推動「無人機群飛」新系統", "url": "https://www.cna.com.tw/news/ait/202610260074.aspx", "date": "2026-10-26", "category": "補助政策", "topic": "數位轉型與AI", "unit": "中央社", "summary": "海洋委員會補助國立成功大學航空太空工程學系副教授闕志哲團隊，研發具垂直起降與定翼特性的「JUMP-20」、「V-Bat」及「Flexrotor」三款無人機之多機型群飛AI任務規劃系統，已完成20架無人機的同步飛行模擬，並將進行硬體迴圈測試、原型機整合與實海域飛行驗證，以提升海域防禦與救難效率，強化全社會防衛韌性。"}, {"title": "勘查宜蘭公糧倉庫受損情形 卓揆：簡化修繕補助行政流程 強化糧倉防災韌性", "url": "https://www.ey.gov.tw/Page/9277F759E41CCD91/ffdec6e3-e48c-49c3-b011-7ba4d3774008", "date": "2026-10-25", "category": "補助政策", "topic": "農業", "unit": "行政院", "summary": "行政院長卓榮泰於10月25日視察宜蘭五結鄉公糧倉庫受損情形，指示農業部核算修繕經費，簡化補助申請流程，倉庫主體最高補助65%，周邊設施最高補助50%，以減輕農會財務負擔並強化防災韌性。"}, {"title": "勘查宜蘭農損情形 卓揆：中央地方攜手做農民後盾 「從優、從速、從寬」辦理救助並加速復耕", "url": "https://www.ey.gov.tw/Page/9277F759E41CCD91/bfcbb4a3-6591-4160-9dba-dec1fa43f62c", "date": "2026-10-25", "category": "補助政策", "topic": "農業", "unit": "行政院", "summary": "行政院長卓榮泰於10月25日視察宜蘭頭城與礁溪，指出全臺農產損失估計逾1億5千萬元。農業部將以每公頃9.5萬元補助柑橘類災害救助，並提供每公頃54萬元補助水平棚架，同時啟動災後復原輔導服務團。另公布「智能韌性設施農業計畫」編列60億元，「建構農業機械示範體系」編列92億元，於116至119年間投入152億元，協助農民復耕與機械化提升。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/ahel/202610265001.aspx"}]}, {"title": "「2026-2027桃園城市紀錄片徵選暨培訓計畫」延長徵件！ 收件至11月2日，創作獎助金與豐富師資等你來提案！", "url": "https://culture.tycg.gov.tw/News_Content.aspx?n=11103&s=1916453", "date": "2026-10-24", "category": "補助政策", "topic": "文化", "unit": "桃園市政府", "summary": "桃園市政府舉辦第十四屆「2026-2027桃園城市紀錄片徵選暨培訓計畫」，延長徵件至11月2日17:00止。計畫分基礎組與進階組，基礎組每組提供10萬元獎助金，進階組每組25萬元，首獎10萬元，評審推薦獎5萬元，總獎金高達200萬元，並提供免費專業影像課程。對象為所有有意從事紀錄片創作的影像工作者與民眾。"}, {"title": "慢行、安心、森呼吸 中山一路升級打造高雄城市客廳新走廊", "url": "https://www.kcg.gov.tw/News_Content.aspx?n=F29A02A9D36C47F0&sms=19902EF36D6B551D&s=3FF17C9369031378", "date": "2026-10-24", "category": "補助成果發表", "topic": "綜合", "unit": "高雄市政府", "summary": "高雄市政府工務局道路養護工程處獲內政部國土署「永續提升人行安全計畫」補助，整體改造中山一路（建國路至民生路）人行環境，改善路段約1.2公里，總經費約2億3,500萬元。人行道統一拓寬至11.5公尺並全面更新鋪面，完善無障礙系統、景觀照明與連續植栽帶，並增設獨立自行車優先道；六合路至八德路東側街廓已率先完成開放通行。"}, {"title": "公告：彰化縣政府受理「都市危險及老舊建築物擬具重建計畫費用」補助申請", "url": "https://www.chcg.gov.tw/TSO/shetou/04bulletin/bulletin02_con.aspx?bull_id=440257", "date": "2026-10-23", "category": "補助資訊", "topic": "社福與生活", "unit": "彰化縣政府", "summary": "彰化縣政府受理「都市危險及老舊建築物擬具重建計畫費用」補助申請，受理期間即日起至115年12月15日止。補助依「都市危險及老舊建築物加速重建條例」第10條及內政部相關作業要點辦理，額度有限，符合資格者請備妥文件儘速向彰化縣政府提出申請，相關疑問可洽彰化縣政府建設處更新發展科（04-7531280）。"}, {"title": "勞動部高分署助中年轉職勇敢跨步 投入長照產業開啟人生下半場", "url": "https://kpptr.wda.gov.tw/News_Content.aspx?n=CD0EC8D01432D27B&sms=90DB06FF66BF4D00&s=3362A76659B1B1B6", "date": "2026-10-23", "category": "補助政策", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動部勞動力發展署高屏澎東分署協助56歲求職者阿原轉職長照，透過「照顧服務缺工獎勵」每月領5,000至7,000元，最長可領10.8萬元，獎勵期限最長18個月，降低轉職經濟壓力，鼓勵中年者投入長照產業。"}, {"title": "內政部：老宅延壽受理1359件公寓沒管委會也能申請", "url": "https://www.cna.com.tw/news/aipl/202610220360.aspx", "date": "2026-10-22", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "內政部表示老宅延壽計畫已受理1359件，包括透天住宅1285案與公寓74案，補助金額自100萬元至1100餘萬元不等，比例約45%至62%。今年編列約17億元預算，預計明年編列約34億元，最快於明年1至5月由各縣市公告第2梯次受理，公寓無管委會亦可申請。"}, {"title": "因應缺工極端氣候農業部152億升級設施優化補助", "url": "https://www.cna.com.tw/news/aipl/202610220210.aspx", "date": "2026-10-22", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "農業部於10月22日說明，行政院會通過116-119年建置智能韌性設施農業及農機輔導體系，兩項計畫合計投入新台幣152億元，其中60億元用於智能韌性設施農業，92億元支援農機示範體系，旨在協助農友升級設施、優化農機補助，提升農業韌性與省工效益。"}, {"title": "亞大醫院展健康台灣深耕成果機器人助醫護降載", "url": "https://www.cna.com.tw/news/ahel/202610220244.aspx", "date": "2026-10-22", "category": "補助成果發表", "topic": "數位轉型與AI", "unit": "中央社", "summary": "亞洲大學附屬醫院於10月22日舉辦健康台灣深耕計畫成果展，展示照護機器人「愛寶」及VR沉浸式臨床教學等應用，說明此類技術可減輕護理師工作負荷、提升醫護人員技術，並透過智慧預警系統縮短門診等候時間，展現衛生福利部補助醫療機構強化醫療韌性的成效。"}, {"title": "公告本署「服務型智慧機器人虛擬場景建置及示範擴散補助計畫」申請事項，自115年10月22日起正式受理申請。", "url": "https://moda.gov.tw/ADI/news/bulletin-board/21168", "date": "2026-10-22", "category": "補助政策", "topic": "數位轉型與AI", "unit": "數位發展部", "summary": "數位發展部數位產業署公告「服務型智慧機器人虛擬場景建置及示範擴散補助計畫」，自2026年10月22日起受理申請，協助產業以高擬真虛擬場景進行服務型機器人應用與功能實證示範。補助比例不超過計畫總經費50%，上限新臺幣2,000萬元，其餘由申請企業自籌；受理至2026年11月6日中午12時截止，採電子申請，執行期間至2028年3月31日止。諮詢專線：台北市電腦商業同業公會（02）2701-9808。"}, {"title": "曠世智能獲政府投資遭質疑蘇巧慧：合法不怕查", "url": "https://www.cna.com.tw/news/aloc/202610220361.aspx", "date": "2026-10-22", "category": "補助政策", "topic": "中小企業與新創", "unit": "中央社", "summary": "經濟部商業發展署於2024年補助新台幣120萬元給曠世智能股份有限公司，該公司董事為蘇巧純。民眾黨與國民黨指稱蘇巧純未依公職人員利益衝突迴避法揭露親屬身分，且2022年台灣中小企業銀行與國家發展基金分別投資2080萬元與1999萬元於曠世智能Pre‑A輪募資。蘇巧慧回應稱相關文件皆依政府規定辦理，合法不怕查。"}, {"title": "校安人力月薪3.6萬起跳 鄭英耀坦言偏低：應達5萬", "url": "https://www.cna.com.tw/news/ahel/202610220133.aspx", "date": "2026-10-22", "category": "補助政策", "topic": "就業與人才", "unit": "中央社", "summary": "行政院9月通過「校園安全韌性2000」計畫，從10月起為期3年，每年挹注地方政府12億元，將國中校安人力由620人增至2000人，月薪比照學務創新人力，約3.6萬至4.7萬元，教育部長鄭英耀認為應提升至5萬元左右。"}, {"title": "卓揆：建置智能韌性設施農業及農機輔導體系 加速農業升級轉型與氣候調適能力", "url": "https://www.ey.gov.tw/Page/9277F759E41CCD91/20c3f1c0-7a57-4567-80ac-48ba7219a24a", "date": "2026-10-22", "category": "補助政策", "topic": "農業", "unit": "行政院", "summary": "行政院長卓榮泰於10月22日說明農業部提出兩項計畫，分別編列60億元與92億元，推動智能韌性設施農業與農機示範體系，以提升農業韌性、機械化與氣候調適能力。"}, {"title": "神盾攜手法國SiPearl CPU合作攻高效能運算及AI市場", "url": "https://www.cna.com.tw/news/afe/202610220339.aspx", "date": "2026-10-22", "category": "補助政策", "topic": "創新研發", "unit": "中央社", "summary": "10月22日，神盾集團與法國SiPearl簽署策略合作，聚焦高效能運算、AI與資料中心。政府去年推動首屆台法創新研發合作補助計畫，促成6項合作，帶動逾12億元研發投資；今年新一輪徵案將擴大至太空、智慧科技、智慧製造、材料生技及綠能科技等領域，台灣提供研發補助，法國透過公共投資銀行提供融資支持。"}, {"title": "海洋文化領航計畫交流工作坊高雄登場促跨域合作", "url": "https://www.cna.com.tw/news/aloc/202610210211.aspx", "date": "2026-10-21", "category": "補助成果發表", "topic": "文化", "unit": "中央社", "summary": "海洋委員會2026年10月21日在高雄展覽館舉辦「海洋文化領航計畫交流工作坊」，包含18場專題交流講座、16攤成果展及海洋文化影片放映，吸引逾150人次參與。海委會主任秘書劉國列表示，「復振航海文化力」4年期計畫經費規模為新台幣3億6600萬元，以「薪傳」、「船藝」、「藝海」3大補助主軸為核心，迄今累計支持102件專案計畫，完成專書出版、繪本製作、文創品開發及造舟航行活動。"}, {"title": "新創追星鐘雀3號、4號升空驗證低軌衛星寬頻通訊技術", "url": "https://www.cna.com.tw/news/ait/202610210310.aspx", "date": "2026-10-21", "category": "補助政策", "topic": "數位轉型與AI", "unit": "中央社", "summary": "國家太空中心表示，「新創追星計畫」第3批的兩顆8U立方衛星「鐘雀3號」與「鐘雀4號」於10月20日晚間7時04分搭乘SpaceX Bandwagon-5任務升空，並於凌晨3點前分別與智利與亞塞拜然地面站完成初步通聯。此次任務將驗證波束跳躍、雙向衛星間鏈路及端到端資料轉傳等關鍵技術，推進低軌衛星寬頻通訊與星間協同運作的技術驗證。"}, {"title": "台水與苗栗縣府簽MOU 4億元打造泰安淨水場強化管線", "url": "https://www.cna.com.tw/news/afe/202610210169.aspx", "date": "2026-10-21", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "台灣自來水公司與苗栗縣政府於10月21日簽署MOU，投入約4.07億元建置泰安淨水場及約23公里下游管線，工程期程自民國116年至119年，淨水場預計於117年完工，供應泰安、大湖、獅潭、公館等鄉鎮民生與產業用水。"}, {"title": "嘉義縣鹿草善東橋動土 嘉邑行善團興建第660座", "url": "https://www.cna.com.tw/news/aloc/202610200108.aspx", "date": "2026-10-20", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "嘉義縣鹿草鄉善東橋於10月20日動土，耗資新台幣600萬元，由嘉義縣政府挹注規劃設計經費，並獲嘉邑行善團全力補助，預計明年中下旬完工，以擴大鴨母寮大排通洪斷面，降低積淹水風險。"}, {"title": "轉知訊息-【轉知】有關116-117年度文化部「博物館與地方文化館深耕計畫」受理提案作業事宜", "url": "https://culture.gov.taipei/News_Content.aspx?n=FCD29F5F5B71E77C&sms=5EAAEFFFF7E20428&s=99CD618C01C666BC", "date": "2026-10-20", "category": "補助政策", "topic": "文化", "unit": "臺北市政府", "summary": "臺北市政府文化局轉知文化部通知，116-117年度「博物館與地方文化館深耕計畫」開始受理提案，請各公、私立提案館所於115年11月4日下午5點前，依文化部規定的提案計畫書格式，完成提案計畫書一式2份（彩色列印並含電子檔），提送臺北市政府文化局彙整。"}, {"title": "「原住民族經濟永續發展計畫--116-117年度產業推升計畫」受理申請", "url": "https://coia.kcg.gov.tw/web_tw/news_detail.php?n=news&appId=Info&id=7618", "date": "2026-10-20", "category": "補助資訊", "topic": "原住民", "unit": "高雄市政府", "summary": "高雄市政府原住民事務委員會公告，「原住民族經濟永續發展計畫--116-117年度產業推升計畫」自即日起受理申請，至115年12月10日（四）下午5點止。申請對象包括跨2個鄉（鎮、市、區）以上的直轄市或縣（市）政府、鄉（鎮、市、區）公所，以及負責人為原住民且原住民成員占比達八成以上的原住民機構、法人或團體。可線上填寫申請表並上傳文件，無網路地區可郵寄紙本至專案辦公室，以郵戳為憑。"}, {"title": "油價持續偏高航空國內線票價平穩續延長", "url": "https://www.cna.com.tw/news/ahel/202610200049.aspx", "date": "2026-10-20", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "交通部表示，因中東戰火致國際油價居高不下，將延長國內航空票價平穩措施，透過中油吸收燃油漲幅，使國內航線燃油價格維持每公升27.25元以下，避免觸發票價調整門檻，相關油價差額將由行政院編列預算回補，持續時間視油價變化而定。"}, {"title": "中市育兒租金補貼每名子女4,000元 經費將用罄籲儘速申請", "url": "https://cleaner.epb.taichung.gov.tw/newsmain.aspx?n_id=25975", "date": "2026-10-20", "category": "補助資訊", "topic": "社福與生活", "unit": "臺中市政府", "summary": "台中市政府住宅發展工程處表示，市府自115年1月1日起受理育兒租金補貼，運用囤房稅稅收減輕居住負擔。每名符合資格未滿12歲子女可獲一次性補助4,000元，補助子女數不設上限，承租社會住宅家庭也可申請。住宅處指出今年申請踴躍，年度經費即將用罄，呼籲符合資格民眾儘速申請或回復意願確認函，經費用罄將停止受理。"}, {"title": "原民會曾智勇主委訪視新北市原住民族服務中心 中央地方攜手打造都會原住民族服務新據點", "url": "https://www.cip.gov.tw/zh-tw/news/data-list/6EBE68EA8288674E/8AD040E473172F3100E8C492BB127D42-info.html", "date": "2026-10-19", "category": "補助成果發表", "topic": "原住民", "unit": "原住民族委員會", "summary": "原住民族委員會曾智勇主委於10月19日前往新北市三重區，視察新北市原住民族服務中心啟用。該中心經活化整建後，轉型為5層樓複合式服務空間，原民會透過「部落之心示範點建置補助計畫」於113年補助新北市政府3,870萬餘元，提供族語學習、文化傳承、就業諮詢等多元服務。"}, {"title": "產學研攜手促成技術落地、推動產業升級 臺南中小企業服務團展現輔導成果", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8842461", "date": "2026-10-19", "category": "補助成果發表", "topic": "中小企業與新創", "unit": "臺南市政府", "summary": "臺南市政府經濟發展局於10月19日舉辦媒體互動，說明「臺南中小企業服務團」協助在地中小企業推動產學研技術鏈結與AI應用，已為21家企業爭取並取得超過2,300萬元的地方與中央補助，涵蓋研發、智慧製造、低碳節能與數位轉型等面向。"}, {"title": "公告116年度疑似或社區精神病人照護優化計畫申請作業須知- 心理健康司", "url": "https://dep.mohw.gov.tw/DOMHAOH/fp-7322-88229-107.html", "date": "2026-10-19", "category": "補助政策", "topic": "社福與生活", "unit": "衛生福利部", "summary": "衛生福利部公告，補助各縣市主辦精神醫療機構（每縣市至多2家；澎湖、金門、連江縣至多1家），針對疑似或社區精神病人提供就醫評估、醫療轉介、追蹤訪視及社區外展照護等服務。"}, {"title": "最新消息-臺北市自115年8月1日起實施補助50歲以上低收及中低收入戶市民接種帶狀疱疹疫苗", "url": "https://www.whhc.gov.taipei/News_Content.aspx?n=B95E00011C122034&sms=78D644F2755ACCAA&s=6139A5D0D447AE66", "date": "2026-10-19", "category": "補助政策", "topic": "社福與生活", "unit": "臺北市政府", "summary": "臺北市自115年8月1日起實施補助，補助對象為50歲以上的低收入及中低收入戶市民，補助內容為接種帶狀疱疹疫苗。此項補助訊息由臺北市萬華區健康服務中心發布，相關規定依發布機關說明辦理。", "also": [{"unit": "臺北市政府", "url": "https://www.gov.taipei/News_Content.aspx?n=D0042A87C2F0270A&sms=78D644F2755ACCAA&s=6139A5D0D447AE66"}, {"unit": "臺北市政府", "url": "https://www.wshc.gov.taipei/News_Content.aspx?n=ED2A9A7BBAE504B7&sms=78D644F2755ACCAA&s=E796DFA4619D3569"}]}, {"title": "部分長者免健保費 石崇良：保費可能調漲轉嫁15到64歲", "url": "https://www.cna.com.tw/news/ahel/202610180038.aspx", "date": "2026-10-18", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "立法院10月16日三讀修正老人福利法部分條文，近1年綜合所得未達申報標準或綜合所得稅率未達20%的長者，由中央主管機關補助全額健保費。衛福部長石崇良表示，中央預算可能無力補健保赤字，恐面臨保費調漲，負擔轉嫁15至64歲族群。衛福部預估約83%長者符合資格，今年所需經費約400億元，2049年增加到628.6億元。"}, {"title": "陳駿季：4年92億元推動農業機械化與智慧化", "url": "https://www.cna.com.tw/news/aloc/202610170084.aspx", "date": "2026-10-17", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "農業部長陳駿季10月17日表示，中央政府推動農業機械化與智慧化，民國115年到118年將編列新台幣92億元補助農機相關經費，要克服全球氣候變遷與勞動力短缺挑戰。他上午出席雲林國際農業機械暨資材展時說，108年起系統性推動農業機械補助，截至目前累計投入77億元，補助範圍已擴及漁業、畜牧業及林業。"}, {"title": "智慧薪火，永續傳承 原民會115年原住民族專門人才頒獎典禮盛大辦理", "url": "https://www.cip.gov.tw/zh-tw/news/data-list/35AE118732EB6BAF/8AD040E473172F312CE0CD1947CCEB21-info.html", "date": "2026-10-17", "category": "補助成果發表", "topic": "原住民", "unit": "原住民族委員會", "summary": "原住民族委員會副主任委員杜張梅莊10月17日出席「115年原住民族專門人才頒獎典禮」，表揚在專利、專業考試、學術專門著作、體育傑出人才及深造教育等五大領域的優秀原住民族人才。原民會表示，今年度專門人才獎勵計畫共1,236位族人獲獎，頒發獎勵金總額近新臺幣2,600萬元，其中體育傑出人才類獎勵人數占比約五成。"}, {"title": "南市支持教師並率先推動教師法律諮詢服務 持續銜接中央補助方案 完善教師法律支持機制", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=16907&s=8842224", "date": "2026-10-16", "category": "補助政策", "topic": "就業與人才", "unit": "臺南市政府", "summary": "臺南市政府教育局115年9月10日與台南律師公會簽署教師法律諮詢服務合作備忘錄，率先推動教師法律諮詢補助計畫。教師面臨正式陳情、檢舉、申訴或接獲學校調查通知時，可自主預約律師諮詢，向公會人才庫律師諮詢每案補助2,500元，非人才庫律師每案補助1,500元。教育部國教署近期規劃的補助則適用教師疑似不適任調查事件，同一事件每人原則最高3萬元，南市將配合提出經費申請。"}, {"title": "百億圓夢計畫行程更動惹議教育部：加強簽約細節", "url": "https://www.cna.com.tw/news/ahel/202610160112.aspx", "date": "2026-10-16", "category": "補助政策", "topic": "就業與人才", "unit": "中央社", "summary": "教育部去年首度推動青年百億海外圓夢基金計畫，傳出有青年被臨時通知計畫中止或行程變動。青年發展署副署長諶亦聰表示，今年起強化簽約細節，大學與海外單位合作須先取得意向書；若因不可抗力須改變行程，將優先尋找替代方案，仍無法執行時，青年署已增訂補償機制，目前規劃為青年申請獎勵金的1成。另規定只有行政庶務項目能委託旅行社辦理。"}, {"title": "中市敬老卡搭計程車提高補助至100點 首週使用人次突破11萬", "url": "https://www.taichung.gov.tw/8868/8872/9962/3393380", "date": "2026-10-16", "category": "補助成果發表", "topic": "社福與生活", "unit": "臺中市政府", "summary": "台中市政府自10月1日起調整敬老愛心卡補助，每趟搭乘計程車最高補助至100點，實施首週服務趟次達11萬2000人次，補助金額達1,100萬元。此項政策維持持卡人每月1000點補助不變，旨在減輕長者及身心障礙者日常交通負擔，交通局表示市府將持續優化服務並提供更周全照顧。"}, {"title": "傅崐萁等提修法未滿6歲免健保費立院付委審查", "url": "https://www.cna.com.tw/news/aipl/202610160200.aspx", "date": "2026-10-16", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "國民黨立委傅崐萁、蘇清泉等17人提案修正兒少權法第27條，增訂未滿6歲兒童的全民健保保險費由中央主管機關全額補助，以減輕家庭育兒負擔、因應少子女化。立法院會10月16日無異議將草案交付社福及衛環委員會審查。"}, {"title": "中央補助經費桃園龜山文化一路至青山路道路通車", "url": "https://www.cna.com.tw/news/aloc/202610160202.aspx", "date": "2026-10-16", "category": "補助成果發表", "topic": "綜合", "unit": "中央社", "summary": "桃園市龜山區文化一路至青山路新闢道路10月16日完工通車，透過內政部生活圈道路計畫獲國土管理署補助約2.14億元，總工程費由原估約8億元降至3.22億元，工期也縮短至430天。內政部表示，已透過多項道路計畫補助桃園108案、逾35億元。"}, {"title": "從知識與情感理解台灣法譯人文社科新書巴黎出版", "url": "https://www.cna.com.tw/news/acul/202610160258.aspx", "date": "2026-10-16", "category": "補助成果發表", "topic": "文化", "unit": "中央社", "summary": "國科會支持、台文館執行的「人文千言萬里：台灣人社科研成果外譯及出版計畫」，10月14日在巴黎hémisphères出版社發表3本法譯新書，主題涵蓋台灣飲食、自然災害與經濟，並陳社科研究與文學作品。計畫今年10月已在倫敦、萊登、巴黎出版，之後將推出中文版。", "also": [{"unit": "國科會", "url": "https://www.nstc.gov.tw/folksonomy/detail/7e4b71cc-ef4c-496c-8bcf-1ccde9668e4d?l=CH&utm_source=rss"}]}, {"title": "立院三讀部分長者免健保費卓榮泰：韓國瑜放任違憲", "url": "https://www.cna.com.tw/news/aipl/202610160328.aspx", "date": "2026-10-16", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "立法院10月16日三讀修正老人福利法第22條，近1年綜合所得未達申報標準或綜所稅率未達20%的長者，健保費由中央全額補助。行政院長卓榮泰批評此案違反預算法，估計中央每年將增加近400億元支出，恐加重青壯族群負擔並排擠其他社福預算。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/ahel/202610160234.aspx"}, {"unit": "中央社", "url": "https://www.cna.com.tw/news/aloc/202610170060.aspx"}, {"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202610160330.aspx"}, {"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202610170189.aspx"}, {"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202610170099.aspx"}]}, {"title": "客委會挹注9900萬元卓蘭圖書館重建計畫邁大步", "url": "https://www.cna.com.tw/news/aloc/202610150333.aspx", "date": "2026-10-15", "category": "補助資訊", "topic": "客家", "unit": "中央社", "summary": "苗栗縣卓蘭鎮立圖書館啟用逾35年，因建物老舊、耐震評估不佳須拆除重建。客委會主委古秀妃10月15日現勘表示，「卓蘭鎮客庄生活交流中心及圖書館新建工程」總經費約1億4645萬元，客委會補助卓蘭鎮公所9900萬元，期許新館成為客家文化復振的重要場域。"}, {"title": "臺南市包租代管累計媒合逾1.5萬件 多元住宅政策助市民安心租屋", "url": "https://www.tainan.gov.tw/News_Content.aspx?n=13370&s=8841991", "date": "2026-10-15", "category": "補助成果發表", "topic": "社福與生活", "unit": "臺南市政府", "summary": "臺南市配合中央推動社會住宅包租代管計畫，107至114年四期計畫已媒合逾1萬2000件，第五期自114年10月起由國家住都中心辦理，至115年9月再媒合逾3000件。市府也配合300億元中央擴大租金補貼專案，115年度受理申請逾10萬件、核定逾8萬件。"}, {"title": "校事會議改革防濫訴教育部補助教師法律諮詢", "url": "https://www.cna.com.tw/news/ahel/202610150153.aspx", "date": "2026-10-15", "category": "補助政策", "topic": "文化", "unit": "中央社", "summary": "教育部10月14日公告施行國教署補助地方政府辦理高級中等以下學校教師法律諮詢作業要點，協助涉及不適任事件調查的教師取得律師諮詢，同一事件以每人補助3萬元為原則，期間自調查小組組成至完成報告，補助比率依地方財力分級，經費專款專用。"}, {"title": "轉知衛生福利部中央健康保險署設籍前新住民健保費補助計畫作業原則", "url": "https://www.bade.tycg.gov.tw/News_Content.aspx?n=5601&s=1900515", "date": "2026-10-15", "category": "補助資訊", "topic": "社福與生活", "unit": "桃園市政府", "summary": "桃園市八德區公所轉知健保署「設籍前新住民健保費補助計畫」作業原則。計畫經費來自內政部新住民發展基金，補助對象為已參加全民健保、經縣市政府核定列冊為低收入戶或中低收入戶的設籍前新住民，含喪偶未再婚或離婚並獨自扶養在臺未成年子女者，須提出申請並獲核可。"}, {"title": "從事精神疾病病人社區支持及復健服務獎勵補助計畫", "url": "https://www.mohw.gov.tw/cp-7284-88209-1.html", "date": "2026-10-15", "category": "補助資訊", "topic": "社福與生活", "unit": "衛生福利部", "summary": "衛生福利部心理健康司公告116年度「從事精神疾病病人社區支持及復健服務獎勵補助計畫」，徵求辦理精神疾病病人社區支持及復健服務之單位提出申請，相關需求說明與檢核表已於部網補助公告專區公開。"}, {"title": "失業勞工子女生活扶助金申請倒數可併領就學減免", "url": "https://www.cna.com.tw/news/ahel/202610140144.aspx", "date": "2026-10-14", "category": "補助資訊", "topic": "就業與人才", "unit": "中央社", "summary": "勞動部提醒，115學年度第1學期「失業勞工在學子女生活扶助金」申請至10月19日截止。非自願離職且子女就讀高中職或大專者可申請，公私立大專每名1.5萬至2.6萬元、高中職4千至6千元，並可與教育部就學減免同時請領。"}, {"title": "辦理推展原住民族長期照顧「雪山坑文化健康站」、「哈崙台文化健康站」及「北區原村文化健康站」公告徵求立案人民團體單位申請", "url": "https://eycc.ey.gov.tw/Page/9FAC64F67005E355/0e3bbd7d-0fca-410e-be62-861ecb6cc864", "date": "2026-10-14", "category": "補助資訊", "topic": "社福與生活", "unit": "行政院", "summary": "臺中市原民會依原民會文化健康站實施計畫，公告徵求立案人民團體申請經營雪山坑、哈崙台及北區原村等3處文化健康站，服務和平區及北區原住民族長者；計畫期程116年全年，補助含設施設備、業務費及照服員費用等，申請至115年10月21日止。"}, {"title": "宜居部落建設計畫–116年整建文化健康站友善空間申請作業須知", "url": "https://eycc.ey.gov.tw/Page/9FAC64F67005E355/5e2e40e6-c448-4bf5-8bab-a04500ff03dd", "date": "2026-10-14", "category": "補助資訊", "topic": "社福與生活", "unit": "行政院", "summary": "臺中市原民會轉知原民會「宜居部落建設計畫–116年整建文化健康站友善空間」申請須知，補助對象為已核定文健站所在縣市政府或執行之公立大專校院，補助公有空間整建，申請至115年10月21日，作業須知與補助標準表公開於市府官網。"}, {"title": "排除障礙 雙軌並進 北分署助熟齡高手提升戰力、續航職場", "url": "https://tkyhkm.wda.gov.tw/News_Content.aspx?n=FE04360B3F5FF536&sms=45F7BA4F91C26F12&s=24ACD154A698FD16", "date": "2026-10-13", "category": "補助資訊", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動部勞動力發展署北分署銀髮人才資源中心推動「五零五零就業網絡補助」與「職務再設計」，雙軌協助中高齡者提升職能並改善職場條件。116年度五零五零就業網絡合作補助受理至115年10月20日，民間團體、學校等可結合在地資源提案。"}, {"title": "彰化青年返鄉創業及創新轉型 青創補助-「黃家魚室」成果", "url": "https://www.chcg.gov.tw/ch2/newsdetail.aspx?bull_id=439694&utm_source=website&utm_medium=list&utm_campaign=news01", "date": "2026-10-13", "category": "補助成果發表", "topic": "中小企業與新創", "unit": "彰化縣政府", "summary": "彰化縣青年黃資勛返鄉創立「黃家魚室」，運用縣府青年創業圓夢補助升級品牌與包裝，開發無刺魚排、寶寶魚片等產品。縣長王惠美前往肯定成果，並指出縣府青創補助最高可達50萬元，已協助139位青年創業、累計補助逾3430萬元。"}, {"title": "轉知本府社會局115年自立脫貧服務Start Now!社政青年就業行動培力計畫", "url": "https://youth.tycg.gov.tw/News_Content.aspx?n=11581&s=1896917", "date": "2026-10-13", "category": "補助資訊", "topic": "就業與人才", "unit": "桃園市政府", "summary": "桃園市政府社會局辦理「Start Now!社政青年就業行動培力計畫」，協助低收入戶及中低收入戶16至35歲青年就業。提供職場探索獎勵金2000元、社會實踐獎勵金1000元，以及證照獎勵與報名費補助，詳情可洽社會局社會救助科。"}, {"title": "總統盼與建築師公會保持溝通攜手提升城市韌性", "url": "https://www.cna.com.tw/news/aipl/202610130301.aspx", "date": "2026-10-13", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "總統出席建築師公會交接典禮時指出，全國屋齡逾30年住宅約516萬戶，政府持續推動都更、危老重建，並提出50億元老宅延壽計畫，協助老屋更新管線、防水與無障礙設施，盼與公會攜手提升城市韌性。"}, {"title": "公告本會「116 年度創業共好計畫申請須知」", "url": "https://www.cip.gov.tw/zh-tw/news/data-list/DD56092E0C92EC1F/84D1101222D03C610A95A0D073BC2EF2-info.html", "date": "2026-10-13", "category": "補助資訊", "topic": "中小企業與新創", "unit": "原住民族委員會", "summary": "原住民族委員會公告「116年度創業共好計畫」申請須知，受理至115年12月10日下午5時；限原住民負責之公司或商號（111至115年成立），補助上限50萬元，原則採線上申請，信用不良或已受其他政府相關補助者不得重複申請。"}, {"title": "運動部於中華民國115年10月5日以運產（四）字第1150401433A號令修正發布「補助運動事業引進關鍵技術及發展國際或自有品牌辦法」。", "url": "https://www.sport.taichung.gov.tw/3390693/post", "date": "2026-10-13", "category": "補助政策", "topic": "文化", "unit": "臺中市政府", "summary": "運動部於115年10月5日以令修正發布「補助運動事業引進關鍵技術及發展國際或自有品牌辦法」，臺中市政府運動局轉知各界，電子檔可於運動部主管法規查詢系統下載，作為運動事業申請關鍵技術與品牌發展相關補助之依據。"}, {"title": "提升公共化教保服務 10年增設4,100班", "url": "https://cpc.ey.gov.tw/Page/8AC028685E311A7/9ecdc3fe-0754-42bf-8a4a-b136d096fa6a", "date": "2026-10-12", "category": "補助政策", "topic": "社福與生活", "unit": "行政院", "summary": "教育部國教署指出，配合少子女化對策與「0-6歲國家一起養2.0」，自106年至115年累計補助增設公共化幼兒園逾4,100班、供應量近27萬名額；115年增班設園經費逾5億元。2歲專班原規劃113至115年增200班已達600班；公共化教保家長每月最多繳2,000元，公立園延長照顧開辦率達9成5。"}, {"title": "有關連江縣北竿鄉公所訂定「連江縣北竿鄉托育補助實施辦法」如附件，詳情請洽該公所。", "url": "https://www.pingzhen.tycg.gov.tw/News_Content.aspx?n=5613&s=1895904", "date": "2026-10-12", "category": "補助資訊", "topic": "社福與生活", "unit": "桃園市政府", "summary": "桃園市平鎮區公所轉知：連江縣北竿鄉公所訂定「連江縣北竿鄉托育補助實施辦法」，自116年1月1日實施。設籍並實際居住北竿、將未滿3歲幼兒送托該鄉公共托育中心者，每位幼兒每月補助新臺幣2,000元；申請人須於托育事實發生起20日內檢具文件向鄉公所民政課申請，經審核後按季撥款。", "also": [{"unit": "彰化縣政府", "url": "https://www.chcg.gov.tw/TSO/fuxing/04bulletin/bulletin02_con.aspx?bull_id=439680"}]}, {"title": "公告徵求辦理本部116年度補(捐)助「中藥藥用植物種植計畫」- 中醫藥司", "url": "https://dep.mohw.gov.tw/DOCMAP/cp-890-88174-108.html", "date": "2026-10-12", "category": "補助資訊", "topic": "中醫藥", "unit": "衛生福利部", "summary": "衛生福利部中醫藥司公告徵求辦理116年度補（捐）助「中藥藥用植物種植計畫」，補助中藥藥用植物種植相關業務。申請作業說明書請至衛福部官網公告訊息區下載；申請期限自公告日起至115年11月27日下午5時止（以本部收文為憑）。申請單位須檢附申請計畫書一式8份函送本部提出申請，逾時概不受理。"}, {"title": "國旅補助平日住宿經費已用26% 花蓮台東宜蘭排前3名", "url": "https://www.cna.com.tw/news/ahel/202610110109.aspx", "date": "2026-10-11", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "交通部觀光署9月起推出國旅補助，平日住宿最高折抵2000元。截至10月7日，15.3億元平日住宿補助經費已使用26%、逾3.9億元，累計折抵逾40萬間房，使用前5名為花蓮、台東、宜蘭、屏東、台南。觀光署表示經費將用罄前2週會公告，目前無追加預算規劃。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/ahel/202610070292.aspx"}]}, {"title": "衛環委員會新會期藍擬修長者免健保費、綠首重審預算", "url": "https://www.cna.com.tw/news/aipl/202610110035.aspx", "date": "2026-10-11", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "立法院新會期衛環委員會召委陳菁徽表示，將優先處理65歲以上長者免繳健保費、老農津貼加碼，以及托育、育兒與增加產假、陪產假等法案；另一位召委王正旭則認為本會期以審完部會預算為最重要任務，食安法與國民年金法也在委員會審查中。"}, {"title": "鳳梨全果變身生活好物大葉大學推農業循環再生", "url": "https://www.cna.com.tw/news/ahel/202610110126.aspx", "date": "2026-10-11", "category": "補助成果發表", "topic": "農業", "unit": "中央社", "summary": "大葉大學執行教育部「循跡里山—八卦台地聚落六級化產業共創計畫」，帶學生到彰化芬園鄉中崙社區，將鳳梨果肉製成醬鳳梨、果皮做酵素清潔劑，並媒合廠商開發鳳梨凍乾，也把鳳梨葉製成手抄紙等，探索農業剩餘資材再利用與地方產業加值。"}, {"title": "家電汰舊換新節能補助年底截止 額度剩不到2成", "url": "https://www.cna.com.tw/news/afe/202610100027.aspx", "date": "2026-10-10", "category": "補助資訊", "topic": "節能減碳", "unit": "中央社", "summary": "經濟部能源署「住宅家電汰舊換新節能補助」將於今年底截止，補助額度剩不到2成。汰換為1級能效冷氣或冰箱每台補助3000元，加計貨物稅退稅最高5000元。112年至115年9月底累計申請607.3萬台。116至118年仍有購買節能電器退還貨物稅措施，每台最高退2000元。"}, {"title": "營養午餐加碼5元食材費用黃敏惠：學童吃得更營養", "url": "https://www.cna.com.tw/news/aloc/202610100125.aspx", "date": "2026-10-10", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "嘉義市長黃敏惠表示，市府今年起實施國中小學生營養午餐全面免費，並已編列預算，明年起每餐再增加5元食材費用。同日嘉義市文財殿頒發教育補助金，115學年度嘉惠嘉義及雲林地區14所學校、399名弱勢學生，23年來累計捐助逾7276萬元。"}, {"title": "新住民子女國際職場體驗35學生赴越南胡志明市參訪", "url": "https://www.cna.com.tw/news/ahel/202610100046.aspx", "date": "2026-10-10", "category": "補助成果發表", "topic": "就業與人才", "unit": "中央社", "summary": "教育部自105年起委託高雄科技大學推動「國際移動力發展計畫」，補助高中職與新南向國家學校交流，並每年遴選新住民子女赴海外企業參訪。今年35名新住民子女學生暑假赴越南胡志明市參訪台商企業，至今已有逾300名學生參與國際職場體驗。"}, {"title": "職安署補助大專院校試辦開課培育職災重建人才", "url": "https://www.cna.com.tw/news/ahel/202610090161.aspx", "date": "2026-10-09", "category": "補助資訊", "topic": "就業與人才", "unit": "中央社", "summary": "勞動部職安署推動職業災害勞工重建服務訓練學程補助試辦計畫，補助設有職能治療等相關科系的大專校院開設學程，讓學生在校即完成職災重建訓練、畢業即可上工。每校補助上限32萬元，可用於人事費與業務費，首年在北、中、南各辦理，每區至少招收12人，先試辦1年再檢討。"}, {"title": "無人機研發補助擴大經部核定27案漢翔獲1億最多", "url": "https://www.cna.com.tw/news/afe/202610090033.aspx", "date": "2026-10-09", "category": "補助成果發表", "topic": "創新研發", "unit": "中央社", "summary": "經濟部「無人機前瞻技術研發與國際商機加速補助計畫」今年收件49案、核定27案，補助約7.8億元，核准率約55%，較去年7案、3.26億元明顯增加。整機類6案獲約2.82億元，關鍵技術類21案獲約4.97億元，以酬載及通訊最多。漢翔獲補助1億元為單案最高，將開發高承載物流無人機。"}, {"title": "馬祖小三通縣民敬老票 2027年補助增為2600元", "url": "https://www.cna.com.tw/news/aloc/202610080332.aspx", "date": "2026-10-08", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "連江縣長王忠銘表示，若議會支持，2027年上路的小三通縣民敬老票新制將採單程免費，每人每年補助上限由2500元調高至2600元，最多可享4次。新制整合馬祖海上交通訂位購票系統，購票時自動計算剩餘補助，不必再持票根申請；補助範圍限馬祖往中國單程。"}, {"title": "政院提修法投入千億助中小微企業升級介接優勢供應鏈", "url": "https://www.cna.com.tw/news/aipl/202610080165.aspx", "date": "2026-10-08", "category": "補助政策", "topic": "中小企業與新創", "unit": "中央社", "summary": "行政院會10月8日通過「中小微企業轉型升級發展條例」草案，經濟部未來8年將加碼1000億元撥入發展基金。草案將商圈、市場、地方特色產業、農企業與觀光旅宿等納入輔導，102.9萬家微型店家也可受惠，並提供普惠貸款、新增農業信保基金，智慧機械、AI與淨零設備投資抵減門檻由100萬元降至25萬元。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202610070341.aspx"}]}, {"title": "海廢變身綠色建材高科大研發廢漁網入料強化邊坡", "url": "https://www.cna.com.tw/news/ahel/202610080105.aspx", "date": "2026-10-08", "category": "補助成果發表", "topic": "創新研發", "unit": "中央社", "summary": "海洋委員會補助高雄科技大學陳松靖團隊，研發將廢漁網與寶特瓶製成「海廢再生結構纖維」拌入噴凝土，取代易鏽蝕的鋼絲網，用於南部泥岩惡地濱海邊坡。每立方公尺可去化6至10公斤海廢塑膠、減碳約27公斤，護坡壽命由5年延長至12年以上，並結合AIoT感測即時監測邊坡安全。"}, {"title": "鼓勵醫療院所連假開診衛福部挹注2.5億獎勵", "url": "https://www.cna.com.tw/news/aipl/202610080200.aspx", "date": "2026-10-08", "category": "補助政策", "topic": "社福與生活", "unit": "中央社", "summary": "衛福部將挹注2.5億元，鼓勵醫療院所在10月至12月國定連假期間開診。連假週日門診的診察費及藥事服務費加成50%，連假期間急診及住院案件的診察費、護理費與藥事服務費也加成50%，以維持就醫可近性、分流急診量能，並參考今年春節假期獎勵經驗辦理。"}, {"title": "內政部補助舊社區自主都更最高1100萬元", "url": "https://www.cna.com.tw/news/aipl/202610070307.aspx", "date": "2026-10-07", "category": "補助資訊", "topic": "社福與生活", "unit": "中央社", "summary": "內政部已公告112至115年中央都市更新基金補助自行實施更新作業須知，由地方政府受理。新制新增更新會成立及前期推動補助100萬元，並將都更事業與權利變換規劃補助由800萬元提高至1000萬元，自主更新社區最高可獲1100萬元補助。相關條例修正草案已送立法院。"}, {"title": "北市診所未完成酒癮訓練衛福部強調不影響補助", "url": "https://www.cna.com.tw/news/ahel/202610070242.aspx", "date": "2026-10-07", "category": "補助資訊", "topic": "社福與生活", "unit": "中央社", "summary": "台北市一家身心診所因部分人員未完成每年8小時酒癮治療繼續教育而調整服務。衛福部表示該診所仍為指定酒癮治療機構，不影響民眾申請「酒癮治療費用補助方案」。全台共132家指定機構，115年編列6200萬元預算，每人每年最高補助4萬元酒癮治療費用。", "also": [{"unit": "中央社", "url": "https://www.cna.com.tw/news/aipl/202610070236.aspx"}]}, {"title": "公告「提升客語社群活力補助作業要點」-116年度「編撰(製)或出版客語教材(具)類」、「客語推廣資訊系統類」及「客語社區營造計畫」相關表件，自即日起至115年10月31日止受理申請", "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=eefd4161-a801-4b39-b3c0-c846f683e72a", "date": "2026-10-07", "category": "補助資訊", "topic": "客家", "unit": "客家委員會", "summary": "客委會「提升客語社群活力補助作業要點」116年度開放受理，包括編撰或出版客語教材（具）類、客語推廣資訊系統類及客語社區營造計畫，即日起至115年10月31日止。歡迎具教材出版或系統開發經驗的公司、財團法人、大專院校，以及社區組織、民間團體、學校或個人申請。"}, {"title": "中醫藥發展計畫將進第二期衛福部：爭取增照護病種", "url": "https://www.cna.com.tw/news/aipl/202610070322.aspx", "date": "2026-10-07", "category": "補助政策", "topic": "綜合", "unit": "中央社", "summary": "衛福部表示，中醫藥發展計畫明年進入第二期，5年共框列77億元預算，將發展結合研究、臨床服務、保健與產業的中醫藥園區，並爭取增加中醫照護病種。衛福部組織法修正後，中醫藥研究所將獨立為行政法人國家中醫研究院。"}, {"title": "助地方農業發展高雄餐飲業者以在地食材入菜", "url": "https://www.cna.com.tw/news/aloc/202610070195.aspx", "date": "2026-10-07", "category": "補助成果發表", "topic": "農業", "unit": "中央社", "summary": "高雄市農業局與高雄萬豪酒店推動「在地食材採購暨主廚共創推廣計畫」並發表成果，6位主廚以11項高雄在地食材推出9道限定菜色，在館內供應一至二季。農業局表示改採「先試菜、再採購、後擴大」模式，建立可持續的採購關係，未來將擴大至更多飯店與企業。"}, {"title": "公告「產業新尖兵計畫」116年度上半年訓練課程延長受理至115年10月31日止", "url": "https://kpptr.wda.gov.tw/News_Content.aspx?n=47645573746633F4&sms=52387778D34E4FE3&s=A0A9B99D8BD7BCA0", "date": "2026-10-06", "category": "補助資訊", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動力發展署高屏澎東分署公告，「產業新尖兵計畫」116年度上半年訓練課程延長受理至115年10月31日。申請對象為財團法人、工商業團體及大專院校，課程以電子電機、工業機械、數位資訊、綠能科技及國際行銷為主，並新增補助學員付費訂閱AI工具措施。"}, {"title": "AI淨零／中市府輔導設置附屬綠能設施推動農業升級綠能發展", "url": "https://www.cna.com.tw/news/aloc/202610060171.aspx", "date": "2026-10-06", "category": "補助成果發表", "topic": "節能減碳", "unit": "中央社", "summary": "台中市農業局輔導農民在菇類栽培場、畜舍、禽舍等農業設施屋頂設置附屬太陽光電，今年至7月底已核發7座容許使用同意，裝置容量接近去年全年，預估年底可突破4000kW。農業局強調須以維持農業生產為前提，並以經營實績審查與抽查避免農地變更使用。"}, {"title": "南投名間茶菁價跌許淑華、温世政各提解方", "url": "https://www.cna.com.tw/news/aipl/202610050190.aspx", "date": "2026-10-05", "category": "補助政策", "topic": "農業", "unit": "中央社", "summary": "南投縣名間鄉茶菁收購價跌至近年低點，縣長許淑華表示已將茶農意見轉給農業部，農業部表示將提供補助，部分直接給茶農、部分給茶商，縣府也會評估由農會協助行銷與採購；民進黨參選人温世政則盼中央提高補助，實質協助茶農與收購業者。"}, {"title": "非自願離職，也有就業保險「職業訓練生活津貼」可請領！", "url": "https://www.mol.gov.tw/1607/1632/1633/99260/post", "date": "2026-10-02", "category": "補助資訊", "topic": "就業與人才", "unit": "勞動部", "summary": "勞動部提醒，非自願離職者經公立就業服務機構安排參加全日制職業訓練，可請領就業保險職業訓練生活津貼。津貼按離職前6個月平均月投保薪資60%計算，最長6個月，扶養眷屬每人加給10%、最高20%；自行報名補習班課程不適用，訓練未滿1個月中途離訓也不發給。"}, {"title": "公告「『大南方新矽谷推動方案』115年度智慧雨林產業創生補助計畫-健康照護領域」示範案、主題案：核定補助名單", "url": "https://moda.gov.tw/ADI/news/bulletin-board/20942", "date": "2026-10-02", "category": "補助成果發表", "topic": "數位轉型與AI", "unit": "數位發展部", "summary": "數位發展部數位產業署公告「大南方新矽谷推動方案」115年度智慧雨林產業創生補助計畫健康照護領域示範案與主題案核定補助名單，名單依計畫名稱筆畫排序列於附件。獲補助單位須依申請須知及執行單位資策會通知，辦理計畫書複核與簽約作業。"}, {"title": "115年度「企業人力資源提升計畫」第3梯次受理申請期間", "url": "https://yct168.wda.gov.tw/News_Content.aspx?n=3457B06B7217EC61&sms=9F8CD839BDD2F62F&s=087B09D58283363D", "date": "2026-10-01", "category": "補助資訊", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動力發展署公告115年度「企業人力資源提升計畫」第3梯次受理期間為10月1日至10月16日，以郵戳為憑。政策性課程或派訓29歲以下青年、中高齡者，外部訓練補助比率可提高至70%。核定後須於11月25日前完成訓練，事業單位應向所在地分署提出申請。"}, {"title": "農業部表揚第8屆百大青農 攜手青農共創臺灣農業新未來", "url": "https://www.moa.gov.tw/theme_data.php?theme=news&sub_theme=agri&id=10296", "date": "2026-09-30", "category": "補助成果發表", "topic": "農業", "unit": "農業部", "summary": "農業部9月30日表揚第8屆百大青農，共106位青年農民獲選，肯定其在科技應用、品牌加值與返鄉帶動地方發展的表現。部長陳駿季並提到，農民退休儲金政府補助比率已提高至60%，農業部也正研議農民育嬰生育補貼，持續改善從農環境。"}, {"title": "10月1日婚假新制上路 新增6日工資補助同步上路", "url": "https://www.mol.gov.tw/1607/1632/1633/99216/", "date": "2026-09-29", "category": "補助政策", "topic": "就業與人才", "unit": "勞動部", "summary": "勞動部修正勞工請假規則，婚假自10月1日起由8日延長為14日，並同步實施友善育兒職場婚孕產假薪資補助要點。雇主依法給付婚假第9至14日工資後，可向勞保局申請全額補助，可線上或郵寄申請。今年受理案件原則於116年1月底前首次核發，雇主須於給付工資後2年內申請。"}, {"title": "本會「推行公事客語無障礙環境補助計畫」116年度收件自115年10月1日起至10月31日受理申請", "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=273&serno=fe58a7a2-59b0-460c-839d-ebf23e27ec7b", "date": "2026-09-29", "category": "補助資訊", "topic": "客家", "unit": "客家委員會", "summary": "客家委員會「推行公事客語無障礙環境補助計畫」116年度自115年10月1日至10月31日受理申請，對象為立案的公私立機關構及團體。補助口譯、臨櫃服務、播音及多媒體資訊服務等，經費不得購置硬體，每案最高補助30萬元，全案匡列預算100萬元。"}, {"title": "本會116年度「藝文團隊補助」自115年10月1日至10月31日受理申請", "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=25&serno=b02e3cd0-df91-4643-a364-cd63e9f7b877", "date": "2026-09-29", "category": "補助資訊", "topic": "客家", "unit": "客家委員會", "summary": "客委會116年度「藝文團隊補助」自115年10月1日至10月31日受理，類別為音樂、戲劇及民俗技藝。補助團隊營運、專業培力、創作版權及展演場租等費用；客家流行音樂團隊可另申請專輯製作發行補助，不列入藝文團隊額度。116年度預算尚待立法院審議。"}, {"title": "數發部發布《NGO/NPO數據轉型手冊》 攜手產官民打造AI驅動公共服務", "url": "https://moda.gov.tw/press/press-releases/20684", "date": "2026-09-22", "category": "補助成果發表", "topic": "數位轉型與AI", "unit": "數位發展部", "summary": "數位發展部舉辦「數據賦能 公益創新」成果分享論壇，發布《NGO/NPO數據轉型操作手冊》，彙整三年來以8個月培力課程與客製化陪跑協助非營利組織整理、運用資料與導入AI的方法與案例，並串聯台灣思科等產業夥伴，促進公益組織與技術端交流合作。"}, {"title": "不只會設計，還能寫程式！ 北分署職訓助青年拓展職能，跨域成為軟體工程師", "url": "https://tkyhkm.wda.gov.tw/News_Content.aspx?n=FE04360B3F5FF536&sms=45F7BA4F91C26F12&s=65FC3CF525CE02ED", "date": "2026-09-21", "category": "補助成果發表", "topic": "就業與人才", "unit": "勞動部勞動力發展署", "summary": "勞動力發展署北分署分享職訓成果案例：25歲數位媒體設計背景的小玟參加400小時「AI數據與雙程式應用班」，學習Java、Python與資料庫，順利轉職軟體工程師。分署提醒，15至29歲青年參加政策性產業職訓，除訓練費補助外，每月還可領8000元學習獎勵金。"}, {"title": "116年度推展原住民族音樂產業補助「音樂製作及行銷」受理申請", "url": "https://www.cip.gov.tw/zh-tw/news/data-list/C78C8EAE23CC8989/39CF6EDD004314A133A6095161A25B23-info.html", "date": "2026-09-17", "category": "補助資訊", "topic": "原住民", "unit": "原住民族委員會", "summary": "原住民族委員會116年度推展原住民族音樂產業補助「音樂製作及行銷」，受理期間為115年10月1日至10月31日。創作、錄製及行銷類須由具中華民國國籍的創作者本人，或依法登記的法人、團體申請；作品創意行銷類則限實際從事音樂製作、發行或行銷的公司或商號。"}, {"title": "企業托育補助新制創造企業留才與員工兼顧育兒需求正面效益！申請倒數2週，請雇主把握時間，於9月底前提出申請！", "url": "https://www.mol.gov.tw/1607/1632/1633/99061/post", "date": "2026-09-16", "category": "補助資訊", "topic": "就業與人才", "unit": "勞動部", "summary": "勞動部企業托育補助新制5月上路，115年度第2期已有800餘家企業申請，9月30日截止。新興建托兒設施最高補助500萬元，已設置者每年最高100萬元，並新增營運費與人事費補助；托兒措施每年最高100萬元，每位員工育兒補貼最高1萬元，補助比率依企業規模為50%至70%。"}, {"title": "116年度客家委員會「推展海內外客家事務交流合作活動補助計畫」受理116年度上半年(1月1日至6月30日辦理)申辦計畫，請符合資格之申請單位自115年10月1日至11月30日提出申請", "url": "https://www.hakka.gov.tw/chhakka/app/data/view?module=hotnews&id=273&serno=aed2ff5d-87c4-4ed9-9bb0-2ba0a40c25c9", "date": "2026-09-15", "category": "補助資訊", "topic": "客家", "unit": "客家委員會", "summary": "客委會「推展海內外客家事務交流合作活動補助計畫」受理116年上半年辦理的活動，申請期間為115年10月1日至11月30日。對象為辦理客家事務的國內民間團體、學校及海外客家團體，補助海外參訪、藝文展演與交流活動，每案最高30萬元，同一對象每年以2案為原則。"}];
